import math 

def simulate ():
    x ,y =0.0 ,0.0 
    heading =0.0 

    steps =[
    (3 ,0 ),# Take 3 steps
    (180 ,0 ),# Turn around
    (3 ,0 ),# Take 3 steps
    (90 ,0 )# Turn right
    ]

    for dist ,turn in steps :
        if turn !=0 :
            heading =(heading +turn )%360 
        x +=dist *math .cos (math .radians (heading ))
        y +=dist *math .sin (math .radians (heading ))

    if math .isclose (x ,0 ,abs_tol =1e-9 )and math .isclose (y ,0 ,abs_tol =1e-9 ):
        print ("Yes")
    else :
        print ("No")

simulate ()

